#include <windows.h>

#include <cstdint>

#include "hybrid/runtime.h"

struct HookEntry {
    uint32_t original;
    const void* replacement;
    const char* name;
    uint32_t return_kind;  // used by tools/difftest.py: EAX bytes that carry the result (0 void, 8 EDX:EAX, 0x10 x87)
};

// Generated by tools/gen_link_symbols.py; terminated by a zero entry.
extern "C" const HookEntry reb_hook_table[];

namespace reb {

static constexpr uint32_t kTextBegin = 0x00401000;
static constexpr uint32_t kTextEnd = 0x00657400;

// REB_DISABLE_HOOKS="all" or a comma-separated list of hex addresses keeps the original code,
// which is how a regression gets bisected to a single reimplemented function.
class DisabledHooks {
public:
    DisabledHooks() {
        DWORD n = GetEnvironmentVariableA("REB_DISABLE_HOOKS", buf_, sizeof buf_);
        if (n >= sizeof buf_) log("REB_DISABLE_HOOKS is %u bytes; the limit is %u — ignored", n, sizeof buf_);
        has_ = n > 0 && n < sizeof buf_;
        all_ = has_ && lstrcmpiA(buf_, "all") == 0;
    }

    bool contains(uint32_t address) const {
        if (all_) return true;
        if (!has_) return false;
        for (const char* p = buf_; *p;) {
            uint32_t v = 0;
            if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) p += 2;
            for (; *p && *p != ','; ++p) {
                char c = *p;
                v = v * 16 + (c <= '9' ? c - '0' : (c | 0x20) - 'a' + 10);
            }
            if (v == address) return true;
            if (*p == ',') ++p;
        }
        return false;
    }

private:
    static char buf_[65536];  // static: a stack array this size would need __chkstk
    bool has_ = false;
    bool all_ = false;
};

char DisabledHooks::buf_[65536];

bool patch_jump(uint32_t from, const void* to) {
    auto* p = reinterpret_cast<uint8_t*>(from);
    DWORD old;
    if (!VirtualProtect(p, 5, PAGE_EXECUTE_READWRITE, &old)) return false;
    int32_t rel = static_cast<int32_t>(reinterpret_cast<uintptr_t>(to) - (from + 5));
    p[0] = 0xE9;
    CopyMemory(p + 1, &rel, 4);
    VirtualProtect(p, 5, old, &old);
    FlushInstructionCache(GetCurrentProcess(), p, 5);
    return true;
}

int install_hooks() {
    DisabledHooks disabled;
    int installed = 0, skipped = 0, failed = 0;
    for (const HookEntry* h = reb_hook_table; h->original; ++h) {
        if (h->original < kTextBegin || h->original + 5 > kTextEnd) {
            log("hook %s: address %08x outside .text", h->name, h->original);
            ++failed;
        } else if (is_capture_target(h->original)) {
            log("hook %s (%08x) left original: capture target", h->name, h->original);
            ++skipped;
        } else if (disabled.contains(h->original)) {
            ++skipped;
        } else if (patch_jump(h->original, h->replacement)) {
            ++installed;
        } else {
            log("hook %s: VirtualProtect failed at %08x", h->name, h->original);
            ++failed;
        }
    }
    log("hooks: %d installed, %d disabled, %d failed", installed, skipped, failed);
    return failed;
}

}  // namespace reb
